def gen(rng):
    def fmt(a, b):
        return a + '\n' + b
    def rs(n, alpha):
        return ''.join(rng.choice(alpha) for _ in range(n))
    tests = [fmt('a', 'a'), fmt('a', 'b'), fmt('abc', 'abc'), fmt('abcdef', 'xyz'), fmt('abcdxyz', 'xyzabcd'),
             fmt('zzzz', 'zz'), fmt('abab', 'baba'), fmt('abcde', 'cdeab')]
    for n in (3, 5, 8, 12, 20):
        for alpha in ('ab', 'abc', 'abcdefghijklmnopqrstuvwxyz'):
            tests.append(fmt(rs(rng.randint(1, n), alpha), rs(rng.randint(1, n), alpha)))
    for _ in range(4):
        base = rs(10, 'abc')
        tests.append(fmt(rs(rng.randint(0, 5), 'abc') + base + rs(rng.randint(0, 5), 'abc'),
                         rs(rng.randint(0, 5), 'abc') + base + rs(rng.randint(0, 5), 'abc')))
    tests.append(fmt('a' * 1000, 'a' * 1000))
    tests.append(fmt('a' * 1000, 'a' * 500 + 'b' + 'a' * 499))
    tests.append(fmt(rs(1000, 'ab'), rs(1000, 'ab')))
    tests.append(fmt(rs(1000, 'abcdefghijklmnopqrstuvwxyz'), rs(1000, 'abcdefghijklmnopqrstuvwxyz')))
    base = rs(600, 'abcd')
    tests.append(fmt(rs(200, 'abcd') + base + rs(200, 'abcd'), rs(400, 'abcd') + base))
    return tests

